        if (comptime @hasField(@TypeOf(cell), "blocks")) if (cell.blocks) |blocks| {
            for (blocks) |block| {
                if (spansHaveScale(block.spans)) return true;
                if (block.table) |child| if (tableHasScale(child, depth + 1)) return true;
            }
        };
    };
    return false;
}
