/// Structural slices are allocated from `a`; all decoded strings borrow `payload`,
/// `expected_title`, or `language_metadata`. Those backing bytes must outlive the result.
pub fn decodeAlloc(
    a: A,
    payload: []const u8,
    expected_title: []const u8,
    expected_kind: format.BlobKind,
    language_metadata: ?format.LanguageMetadata,
) !types.Stored {
    return decodeImpl(a, payload, expected_title, expected_kind, language_metadata, null);
}

/// Commit measurements only after ordinary framing and semantic validation pass.
pub fn decodeWithMetricsAlloc(
    a: A,
    payload: []const u8,
    expected_title: []const u8,
    expected_kind: format.BlobKind,
    language_metadata: ?format.LanguageMetadata,
    metrics: *DecodeMetrics,
) !types.Stored {
    var observed: DecodeMetrics = .{};
    const stored = try decodeImpl(a, payload, expected_title, expected_kind, language_metadata, &observed);
    metrics.* = observed;
    return stored;
}

fn decodeImpl(
    a: A,
    payload: []const u8,
    expected_title: []const u8,
    expected_kind: format.BlobKind,
    language_metadata: ?format.LanguageMetadata,
    metrics: ?*DecodeMetrics,
) !types.Stored {
    if (payload.len < magic.len) return error.InvalidPresentation;
    const owner_geometry_header = std.mem.eql(u8, payload[0..magic.len], owner_geometry_magic);
    const authored_presentation_header = std.mem.eql(u8, payload[0..magic.len], authored_presentation_magic);
    const authored_census: u8 = if (authored_presentation_header) blk: {
        if (payload.len < 9 or payload[8] == 0 or payload[8] & ~authored_presentation_features != 0) return error.InvalidPresentation;
        break :blk payload[8];
    } else 0;
    const cell_heights_enabled = authored_census & cell_box_height_feature != 0;
    const principal_enabled = authored_census & principal_viewport_feature != 0;
    const phonos_enabled = authored_census & authored_phonos_feature != 0;
    const a_header = authored_presentation_header or std.mem.eql(u8, payload[0..magic.len], resolved_style_borders_magic);
