    const media = [_]types.Media{.{ .file = "Example.svg", .kind = .image, .caption = "caption" }};
    const stored: types.Stored = .{ .entry = .{ .title = "entry", .kind = .supplemental, .sections = &sections, .references = &refs, .media = &media } };
