    var accepted: Reader = .{ .a = a, .version = .container_fonts, .bytes = encoder.out.items };
    try std.testing.expectEqualDeep(@as(?types.CellStyle, .{ .text_align = .left, .opacity = 0.2 }), try accepted.cellStyle());
