        .sections = &.{.{ .level = 2, .title = "Rich", .blocks = &.{.{ .kind = .paragraph, .figure = outer }} }},
        .media = &.{.{ .file = "Picture.svg", .kind = .image, .caption = "Picture" }} } };
    const mixed_bytes = try encodeAlloc(a, mixed);
