        try std.testing.expectEqualSlices(u8, bytes, try encodeBuildAlloc(a, entry.display_title, entry.sections, entry.organization, entry.references, entry.media));
        for ([_]u8{ 'H', 'J', 'K', 'L' }) |header| {
