    var padding = edges; padding.top = .{ .unit = .em, .value = 1.25 };
    var borders = types.ContainerBorderEdges.all(.none);
    borders.top = .{ .dashed = .{ .width = .{ .unit = .px, .value = 1 }, .color = .{ .rgb = "#a2a9b1" } } };
    var style = StyledSectionCodecTest.style;
