    const font: types.InlineFontSnapshot = .{ .font_features = .seven_on, .font_family = .sans_serif };
    var snapshot: Encoder = .{ .a = a, .version = .container_fonts, .inline_styles = true, .capability_p = true }; defer snapshot.deinit();
