test "fixed atomic inline box uses the Android same-owner geometry bytes and keeps exterior text" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const px: types.StyleLength = .{ .unit = .px, .value = 0 };
    const em: types.StyleLength = .{ .unit = .em, .value = 1.5 };
    const child: types.Span = .{ .text = "\u{a0}", .role = .label, .font_scale = 0.9, .font_scale_basis = .normal_body,
        .inline_style = .{ .font_normalized = true } };
    const edge: types.InlineBoxBorderEdge = .{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = .{ .rgb = "#000000" } } };
    var group: types.InlineBoxGroup(types.Span) = .{ .padding = .all(px), .border = .all(edge), .spans = &.{child},
        .atomic_layout = .{ .width = em, .height = em, .margins = .{ .top = .{ .unit = .px, .value = 1 },
            .right = px, .bottom = .{ .unit = .px, .value = 1 }, .left = px },
            .box_sizing = .content_box, .text_align = .start, .wrap = .normal } };
    var span = child; span.text = ""; span.background = "#ff0000"; span.inline_box_group = &group;
    const stored: types.Stored = .{ .entry = .{ .title = "fixed atomic box", .kind = .supplemental,
        .display_title = &.{ span, .{ .text = "\u{a0}Oxygen" } } } };
    const payload = try encodeAlloc(a, stored);
    const decoded = try decodeAlloc(a, payload, stored.entry.title, stored.entry.kind, null);
    const T = RoundedInlineBox39CodecTest;
    var raw = T.encoder(a); defer raw.deinit();
    try raw.span(span);
    try std.testing.expectEqual(@as(u8, 0x40), raw.out.items[try T.fontFieldsOffset(a, raw.out.items)] & 0x60);
    const geometry = [_]u8{ 1, 0, 0, 192, 63, 1, 0, 0, 192, 63, 0, 0, 0, 128, 63,
        0, 0, 0, 0, 0, 0, 0, 0, 128, 63, 0, 0, 0, 0, 0, 0, 0, 0, 0 };
    try std.testing.expectEqualSlices(u8, &geometry, raw.out.items[raw.out.items.len - geometry.len ..]);
    try std.testing.expectEqualDeep(group.atomic_layout, decoded.entry.display_title[0].inline_box_group.?.atomic_layout);
    try std.testing.expectEqualStrings("\u{a0}", decoded.entry.display_title[0].inline_box_group.?.spans[0].text);
    try std.testing.expectEqualStrings("\u{a0}Oxygen", decoded.entry.display_title[1].text);
    const BuildRole = enum { normal, label };
    const BuildSpan = struct {
        kind: types.InlineKind = .text, role: BuildRole = .normal,
        flags: packed struct(u8) { bold: bool = false, italic: bool = false, code: bool = false,
            small: bool = false, superscript: bool = false, subscript: bool = false,
            strike: bool = false, underline: bool = false } = .{},
        text: []const u8 = "", target: []const u8 = "", language: []const u8 = "",
        classes: []const u8 = "", direction: []const u8 = "", background: ?[]const u8 = null,
        font_scale: ?f32 = null, font_scale_basis: types.FontScaleBasis = .context,
        inline_style: ?types.InlineTextStyle = null,
        inline_box_group: ?*const types.InlineBoxGroup(@This()) = null,
    };
    const build_child: BuildSpan = .{ .text = child.text, .role = .label, .font_scale = child.font_scale,
        .font_scale_basis = child.font_scale_basis, .inline_style = child.inline_style };
    const build_group: types.InlineBoxGroup(BuildSpan) = .{ .padding = group.padding, .border = group.border,
        .atomic_layout = group.atomic_layout, .spans = &.{build_child} };
    var build_owner = build_child;
    build_owner.text = "";
    build_owner.background = span.background;
    build_owner.inline_box_group = &build_group;
    const build_spans = [_]BuildSpan{ build_owner, .{ .text = "\u{a0}Oxygen" } };
    try std.testing.expectEqualSlices(u8, payload, try encodeBuildAlloc(a, &build_spans,
        stored.entry.sections, stored.entry.organization, stored.entry.references, stored.entry.media));

    // Every shortened fixed suffix must fail before a partial atom is accepted.
    for (1..geometry.len + 1) |missing| {
        var truncated = T.reader(a, raw.out.items[0 .. raw.out.items.len - missing]);
        try std.testing.expectError(error.InvalidPresentation, truncated.span());
    }
    const font_fields_at = try T.fontFieldsOffset(a, raw.out.items);
    const conflicting_radius = try a.dupe(u8, raw.out.items);
    conflicting_radius[font_fields_at] |= 0x20;
    var conflicting_input = T.reader(a, conflicting_radius);
    try std.testing.expectError(error.InvalidPresentation, conflicting_input.span());

    // Change only the declaring font and retain the original normalized child.
    const inconsistent_font = try a.dupe(u8, raw.out.items);
    std.mem.writeInt(u32, inconsistent_font[font_fields_at + 1 ..][0..4],
        @bitCast(@as(f32, 1.1)), .little);
    var inconsistent_input = T.reader(a, inconsistent_font);
    try std.testing.expectError(error.InvalidPresentation, inconsistent_input.span());
    var inconsistent_child = child;
    inconsistent_child.font_scale = 1.1;
    group.spans = &.{inconsistent_child};
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    group.spans = &.{child};

    group.radius = .{ .unit = .px, .value = 0 };
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    group.radius = null;
    var unsafe_child = child; unsafe_child.text = " ";
    group.spans = &.{unsafe_child};
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
}

test "responsive container flow prefix is closed and capability gated" {
    const a = std.testing.allocator;
    const screen: types.ContainerScreenMaxWidth = .{ .max_width_px = 720, .layout = .flow };
    var enc: Encoder = .{ .a = a, .version = .container_fonts };
    defer enc.deinit();
    try std.testing.expectError(error.InvalidPresentation, enc.containerScreen(screen));
    enc.responsive_container_flow_enabled = true;
    try enc.containerScreen(screen);
    var dec: Reader = .{ .a = a, .version = .container_fonts, .bytes = enc.out.items, .pos = 0 };
    try std.testing.expectError(error.InvalidPresentation, dec.containerScreen());
    dec.pos = 0;
    dec.responsive_container_flow_enabled = true;
    const decoded = try dec.containerScreen();
    try std.testing.expectEqual(screen.max_width_px, decoded.max_width_px);
    try std.testing.expectEqual(screen.layout, decoded.layout);
    try std.testing.expectEqual(enc.out.items.len, dec.pos);
    const invalid_extensions = [_]u8{ 0, 2, 3 };
    for (invalid_extensions) |extensions| {
        enc.out.items[5] = extensions;
        dec.pos = 0;
        try std.testing.expectError(error.InvalidPresentation, dec.containerScreen());
    }
    dec.pos = 0;
    dec.bytes = enc.out.items[0..5];
    try std.testing.expectError(error.InvalidPresentation, dec.containerScreen());
}

test "DPRa responsive container flow checks the whole record and advertised census" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const leaf = [_]types.Block{.{ .kind = .paragraph, .spans = &.{.{ .text = "Retained child" }} }};
    var inner = [_]types.Block{.{ .kind = .container, .container = .{ .style = .{}, .blocks = &leaf } }};
    var following = [_]types.ContainerScreenMaxWidth{.{ .max_width_px = 400, .clear = .none }};
    var blocks = [_]types.Block{.{ .kind = .container, .container = .{
        .style = .{ .layout = .flex_row, .screen_max_width = .{
            .max_width_px = 720, .width = .auto, .layout = .flow, .following_rules = &following,
        } },
        .blocks = &inner,
    } }};
    const stored: types.Stored = .{ .entry = .{ .title = "responsive-flow", .kind = .supplemental,
        .sections = &.{.{ .level = 2, .title = "Body", .blocks = &blocks }},
    } };
    const bytes = try encodeAlloc(a, stored);
    try std.testing.expectEqualStrings(resolved_style_borders_magic, bytes[0..4]);
    try std.testing.expectEqual(responsive_container_flow_feature, std.mem.readInt(u32, bytes[4..8], .little));
    const decoded = try decodeAlloc(a, bytes, stored.entry.title, stored.entry.kind, null);
    try std.testing.expectEqualDeep(stored, decoded);
    try types.validateStored(a, decoded, stored.entry.title, stored.entry.kind, null);
    try std.testing.expectEqualSlices(u8, bytes, try encodeBuildAlloc(a, stored.entry.display_title,
        stored.entry.sections, stored.entry.organization, stored.entry.references, stored.entry.media));

    const prefix = [_]u8{ 0xd0, 2, 0, 0, 0x81, container_screen_flow_extension };
    const index = std.mem.indexOf(u8, bytes, &prefix) orelse return error.TestExpectedResponsivePrefix;
    try std.testing.expect(std.mem.indexOf(u8, bytes[index + prefix.len ..], &prefix) == null);
    const changed = try a.dupe(u8, bytes);
    for ([_]u8{ 0, 2, 3 }) |extension| {
        // The legacy width keeps this rule nonempty when its extension is zero.
        // That mutation challenges the global census, not empty-rule validation.
        changed[index + 5] = extension;
        try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, changed, stored.entry.title, stored.entry.kind, null));
    }
    @memcpy(changed, bytes);
    std.mem.writeInt(u32, changed[4..8], 0, .little);
    try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, changed, stored.entry.title, stored.entry.kind, null));
    for ([_]u32{ 0x200000, 0x400000, 0x800000, 0x80000000 }) |old_or_reserved| {
        std.mem.writeInt(u32, changed[4..8], old_or_reserved, .little);
        try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, changed, stored.entry.title, stored.entry.kind, null));
        std.mem.writeInt(u32, changed[4..8], responsive_container_flow_feature | old_or_reserved, .little);
        try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, changed, stored.entry.title, stored.entry.kind, null));
    }
    try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, bytes[0 .. index + 5], stored.entry.title, stored.entry.kind, null));
    const trailing = try std.mem.concat(a, u8, &.{ bytes, &.{0} });
    try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, trailing, stored.entry.title, stored.entry.kind, null));

    blocks[0].container.?.style.layout = .flow;
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    blocks[0].container.?.style.layout = .flex_row;
    blocks[0].container.?.style.flex_column_gap = .{ .unit = .px, .value = 3 };
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    blocks[0].container.?.style.flex_column_gap = null;
    following[0].max_width_px = 720;
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    following[0].max_width_px = 400;
    inner[0].container.?.style.flex_item = .none;
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    inner[0].container.?.style.flex_item = null;
    const plain = inner[0];
    const zero: types.StyleLength = .{ .unit = .px, .value = 0 };
    const inset: types.StyleLength = .{ .unit = .em, .value = 0.2 };
    var padding = types.StyleEdges.all(zero);
    padding.left = .{ .unit = .em, .value = 0.8 };
    inner[0] = .{ .kind = .indent, .depth = 1, .list_path = ":", .description_body = .{
        .before = .{ .top = inset, .bottom = inset, .left = inset, .width = .{ .unit = .px, .value = 1 },
            .fill = .{ .rgb = "#cccccc" } },
        .box = .{ .style = .{ .margins = types.StyleEdges.all(zero), .padding = padding,
            .owner_font_scale = 1, .positioning = .relative_auto }, .blocks = &leaf },
    } };
    try std.testing.expect(types.validDescriptionOwner(inner[0]));
    try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
    inner[0] = plain;
    blocks[0].container.?.style.screen_max_width.?.layout = null;
    const legacy = try encodeAlloc(a, stored);
    try std.testing.expect(!std.mem.eql(u8, resolved_style_borders_magic, legacy[0..4]));
    try std.testing.expectEqualDeep(stored, try decodeAlloc(a, legacy, stored.entry.title, stored.entry.kind, null));
}

test "DPRa source anchors and responsive flow retain independent owners and reject ambiguous destinations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const leaf = [_]types.Block{.{ .kind = .paragraph, .spans = &.{.{ .text = "Retained child" }} }};
    const inner = [_]types.Block{.{ .kind = .container, .container = .{ .style = .{}, .blocks = &leaf } }};
    const following = [_]types.ContainerScreenMaxWidth{.{ .max_width_px = 400, .clear = .none }};
    const id = "Енглески:_Q828";
    var blocks = [_]types.Block{
        .{ .kind = .definition, .depth = 1, .list_path = "#", .number = "1", .spans = &.{.{ .text = "The Americas." }} },
        .{ .kind = .definition, .depth = 1, .list_path = "#", .number = "2", .spans = &.{.{ .text = "The US." }} },
        .{ .kind = .container, .container = .{
            .style = .{ .layout = .flex_row, .screen_max_width = .{ .max_width_px = 720, .width = .auto, .layout = .flow, .following_rules = &following } },
            .blocks = &inner,
        } },
    };
    var sections = [_]types.Section{.{ .level = 2, .title = "Body", .anchor = "Body", .blocks = &blocks }};
    const stored: types.Stored = .{ .entry = .{ .title = "America", .kind = .supplemental, .sections = &sections } };
    const ordinary = try encodeAlloc(a, stored);
    try std.testing.expectEqual(@as(u32, 0x01000000), std.mem.readInt(u32, ordinary[4..8], .little));
    blocks[0].anchor = id;
    blocks[1].anchor = "Енглески:_Q830";
    const e = stored.entry;
    const mixed = try encodeAlloc(a, stored);
    try std.testing.expectEqual(@as(u32, 0x09000000), std.mem.readInt(u32, mixed[4..8], .little));
    try std.testing.expectEqualSlices(u8, mixed, try encodeBuildAlloc(a, e.display_title, e.sections, e.organization, e.references, e.media));
    try std.testing.expectEqualDeep(stored, try decodeAlloc(a, mixed, e.title, e.kind, null));

    const crossed = try a.dupe(u8, mixed);
    // Cross just the second source ID in an otherwise valid dual-feature wire record.
    const second = std.mem.indexOf(u8, crossed, blocks[1].anchor) orelse return error.TestExpectedSecondAnchor;
    @memcpy(crossed[second..][0..id.len], id);
    try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, crossed, e.title, e.kind, null));
    @memcpy(crossed, mixed);
    for ([_]u32{ 0x01000000, 0x08000000, 0x09800000 }) |flags| {
        std.mem.writeInt(u32, crossed[4..8], flags, .little);
        try std.testing.expectError(error.InvalidPresentation, decodeAlloc(a, crossed, e.title, e.kind, null));
    }
    for (0..3) |which| {
        switch (which) {
            0 => blocks[1].anchor = id,
            1 => { blocks[1].anchor = ""; sections[0].anchor = id; },
            2 => { sections[0].anchor = "Body"; sections[0].anchor_fallback = id; },
            else => unreachable,
        }
        try std.testing.expectError(error.InvalidPresentation, types.validateStored(a, stored, e.title, e.kind, null));
        try std.testing.expectError(error.InvalidPresentation, encodeAlloc(a, stored));
        try std.testing.expectError(error.InvalidPresentation, encodeBuildAlloc(a, e.display_title, e.sections, e.organization, e.references, e.media));
    }
    sections[0].anchor_fallback = "";
    blocks[0].anchor = "";
    try std.testing.expectEqualSlices(u8, ordinary, try encodeAlloc(a, stored));
}

